import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int L = fs.nextInt();
        int C = fs.nextInt();

        int MAXV = 26 * 26;
        int[][] grid = new int[L][C];
        long[] rowSum = new long[L];
        long[] colSum = new long[C];

        int[][] rowCount = new int[L][MAXV];
        int[][] colCount = new int[C][MAXV];
        boolean[][] varInRow = new boolean[MAXV][L];
        boolean[][] varInCol = new boolean[MAXV][C];

        ArrayList<Integer>[] varRows = new ArrayList[MAXV];
        ArrayList<Integer>[] varCols = new ArrayList[MAXV];
        for (int i = 0; i < MAXV; i++) {
            varRows[i] = new ArrayList<>();
            varCols[i] = new ArrayList<>();
        }

        Map<String, Integer> idMap = new HashMap<>();
        ArrayList<String> names = new ArrayList<>();

        for (int i = 0; i < L; i++) {
            for (int j = 0; j < C; j++) {
                String name = fs.next();
                Integer idObj = idMap.get(name);
                int id;
                if (idObj == null) {
                    id = names.size();
                    idMap.put(name, id);
                    names.add(name);
                } else {
                    id = idObj;
                }

                grid[i][j] = id;
                rowCount[i][id]++;
                colCount[j][id]++;

                if (!varInRow[id][i]) {
                    varInRow[id][i] = true;
                    varRows[id].add(i);
                }
                if (!varInCol[id][j]) {
                    varInCol[id][j] = true;
                    varCols[id].add(j);
                }
            }
            rowSum[i] = fs.nextInt();
        }

        for (int j = 0; j < C; j++) {
            colSum[j] = fs.nextInt();
        }

        int V = names.size();
        boolean[] known = new boolean[V];
        long[] value = new long[V];

        int[] rowUnknown = new int[L];
        int[] colUnknown = new int[C];
        long[] rowKnownSum = new long[L];
        long[] colKnownSum = new long[C];

        for (int i = 0; i < L; i++) {
            int cnt = 0;
            for (int id = 0; id < V; id++) {
                if (rowCount[i][id] > 0) cnt++;
            }
            rowUnknown[i] = cnt;
        }

        for (int j = 0; j < C; j++) {
            int cnt = 0;
            for (int id = 0; id < V; id++) {
                if (colCount[j][id] > 0) cnt++;
            }
            colUnknown[j] = cnt;
        }

        int solved = 0;
        while (solved < V) {
            int type = -1;
            int idx = -1;

            for (int i = 0; i < L; i++) {
                if (rowUnknown[i] == 1) {
                    type = 0;
                    idx = i;
                    break;
                }
            }

            if (type == -1) {
                for (int j = 0; j < C; j++) {
                    if (colUnknown[j] == 1) {
                        type = 1;
                        idx = j;
                        break;
                    }
                }
            }

            if (type == -1) break;

            int unknownId = -1;
            long val = 0;

            if (type == 0) {
                int r = idx;
                for (int j = 0; j < C; j++) {
                    int id = grid[r][j];
                    if (!known[id]) {
                        unknownId = id;
                        break;
                    }
                }
                int mult = rowCount[r][unknownId];
                val = (rowSum[r] - rowKnownSum[r]) / mult;
            } else {
                int c = idx;
                for (int i = 0; i < L; i++) {
                    int id = grid[i][c];
                    if (!known[id]) {
                        unknownId = id;
                        break;
                    }
                }
                int mult = colCount[c][unknownId];
                val = (colSum[c] - colKnownSum[c]) / mult;
            }

            known[unknownId] = true;
            value[unknownId] = val;
            solved++;

            for (int rr : varRows[unknownId]) {
                rowUnknown[rr]--;
                rowKnownSum[rr] += val * rowCount[rr][unknownId];
            }

            for (int cc : varCols[unknownId]) {
                colUnknown[cc]--;
                colKnownSum[cc] += val * colCount[cc][unknownId];
            }
        }

        Integer[] order = new Integer[V];
        for (int i = 0; i < V; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> names.get(a).compareTo(names.get(b)));

        StringBuilder sb = new StringBuilder();
        for (int id : order) {
            sb.append(names.get(id)).append(' ').append(value[id]).append('\n');
        }
        System.out.print(sb);
    }
}
